(() => {
  const cfg = window.__MOCKCFG || { sample: 'ok' };
  const store = window.__store = JSON.parse(localStorage.getItem('__mockdb') || '{}');
  const persist = () => localStorage.setItem('__mockdb', JSON.stringify(store));
  window.__mock = { calls: [], sent: [], saves: [] };
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const docRef = (path) => ({ id: path.split('/').pop(), path, get: async () => ({ id: path.split('/').pop(), exists: !!store[path], data: () => store[path] && JSON.parse(JSON.stringify(store[path])), metadata: {} }), set: async (d) => { const s = JSON.stringify(d); if (s.length > 256 * 1024) throw { code: 'invalid_argument' }; store[path] = JSON.parse(s); persist(); }, update: async (d) => { Object.assign(store[path], d); persist(); }, delete: async () => { delete store[path]; persist(); } });
  const query = (col, filters = [], ord = null, lim = 1000) => ({
    where: (f, op, v) => query(col, [...filters, [f, op, v]], ord, lim), orderBy: (f, dir) => query(col, filters, [f, dir], lim), limit: (n) => query(col, filters, ord, n),
    get: async () => { let docs = Object.keys(store).filter(k => k.startsWith(col + '/') && k.split('/').length === col.split('/').length + 1).map(k => ({ id: k.split('/').pop(), exists: true, data: () => JSON.parse(JSON.stringify(store[k])), metadata: {} }));
      docs = docs.filter(d => filters.every(([f, op, v]) => op === '==' ? d.data()[f] === v : true)); if (ord) docs.sort((a, b) => (a.data()[ord[0]] - b.data()[ord[0]]) * (ord[1] === 'desc' ? -1 : 1)); docs = docs.slice(0, lim); return { docs, size: docs.length, empty: !docs.length }; } });
  const db = { doc: docRef, collection: (c) => Object.assign(query(c), { doc: (id) => docRef(c + '/' + id) }) };
  const json = async (prompt, opts) => { window.__mock.calls.push({ prompt, opts }); await sleep(300); if (cfg.sample === 'deny') throw { code: 'not_granted', message: 'no' };
    if (/3 clearly different concepts/.test(prompt)) return { concepts: [0, 1, 2].map(i => ({ name: ['The Living Lab', 'Pulse of the Gulf', 'Night at the Atrium'][i], bigIdea: 'A conference designed as a working laboratory where every session ends in a decision. Delegates leave with a shared regional action plan.', feeling: 'Ready to act', signature: 'A live vote that projects the region’s priorities on the atrium wall', mood: ['Scientific', 'Bold', 'Premium'], spaces: [{ name: 'Arrival atrium', purpose: 'Welcome and badges', cap: '600' }, { name: 'Main hall', purpose: 'Plenaries', cap: '800' }, { name: 'Lab rooms', purpose: 'Workshops', cap: '60' }, { name: 'Partner street', purpose: 'Exhibition', cap: '400' }], programme: [{ time: '08:00', title: 'Arrival', space: 'Arrival atrium', who: 'Hosts' }, { time: '09:00', title: 'Opening', space: 'Main hall', who: 'Chair' }, { time: '11:00', title: 'Labs', space: 'Lab rooms', who: 'Facilitators' }, { time: '13:00', title: 'Lunch on partner street', space: 'Partner street', who: '' }, { time: '16:00', title: 'Live vote and close', space: 'Main hall', who: 'Chair' }], online: 'Online delegates vote live and see their pin on the wall.' })) };
    if (/run of show/.test(prompt)) return { programme: [{ time: '09:00', title: 'Welcome', space: 'Main hall', who: 'Host' }] };
    if (/audience mix/.test(prompt)) return { segments: [{ label: 'Consultants', pct: 50 }, { label: 'Fellows', pct: 30 }, { label: 'Nurses', pct: 20 }] };
    if (/filling in an event planning form/.test(prompt)) { window.__mock.qf = { prompt, images: opts.images ? opts.images.length : 0 };
      return { type: 'gala', path: 'new', format: 'Hybrid', basics: { title: 'Excellence Awards Night 2027', attendance: '400 guests', location: 'Dubai', languages: ['English', 'Arabic', 'Klingon'] }, concept: { mood: ['Premium', 'Warm'], feeling: 'Proud and moved' }, spaces: [{ name: 'Red carpet', purpose: 'Arrival', cap: '400' }, { name: 'Ballroom', purpose: '30 x 40 m', cap: '400' }], programme: [{ time: '19:00', title: 'Red carpet', space: 'Red carpet' }, { time: '20:00', title: 'Dinner', space: 'Ballroom' }, { time: '21:00', title: 'Awards', space: 'Ballroom' }], partners: { has: 'yes', list: [{ name: 'Acme Bank', tier: 'gold' }] }, delivery: { deadline: '2027-02-15', owner: 'Lina' } }; }
    return { spaces: [{ name: 'A', purpose: 'x', cap: '10' }] }; };
  const room = { canSendToClaudeSession: async () => 'available', sendToClaudeSession: async (d, o) => { window.__mock.sent.push({ d, o }); return { to: 'pane' }; }, onPeers: () => () => {}, presence: async () => {} };
  const user = { id: async () => 'u_me', can: async () => true, canEdit: async () => true, me: async () => ({ id: 'u_me', name: 'Medhat' }) };
  const assets = { upload: async (b, o) => { await sleep(50); const id = Math.random().toString(16).slice(2).padEnd(32, '0').slice(0, 32); window.__mock.uploads = (window.__mock.uploads || 0) + 1; return { id, url: '/_blob/' + id, sizeBytes: b.size, contentType: (o && o.type) || b.type }; }, delete: async () => ({ deleted: true }) };
  const downloads = { save: async (r) => { window.__mock.saves.push(r); return { status: 'saved' }; } };
  window.claude = { use: async (n) => { await sleep(30); return { db, user, sample: cfg.sample ? Object.assign(async () => ({ text: '' }), { json, limits: async () => ({ maxPromptBytes: 262144, images: { maxCount: 5, maxInputBytes: 2e7, mediaTypes: ['image/png', 'image/jpeg'] } }) }) : null, assets: cfg.assets === false ? null : assets, room, downloads }[n] || null; } };
})();
